pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // Adversarial environment: the bug makes onlyDepositor always revert.
        // We must be able to make a call that succeeds on the reference but fails on the mutant.
        // Prank the real DEPOSITOR_ACCOUNT so the reference's modifier passes.
        vm.prank(c.DEPOSITOR_ACCOUNT());
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            // On reference: the call succeeds and batcherHash is updated.
            assertEq(c.batcherHash(), _batcherHash);
        } catch {
            // On mutant: the call reverts; we fall here and fail the assertion.
            assertTrue(false, "setL1BlockValues reverted unexpectedly on mutant");
        }
    }
}
